"""在公开渲染帧验证独立审查要求的标记位置，而非断言SVG内部实现。"""
from pathlib import Path
import subprocess,json,sys
p=Path(sys.argv[1]);raw=subprocess.check_output(['ffmpeg','-v','error','-i',str(p),'-f','rawvideo','-pix_fmt','rgb24','-'])
scale=1920/1672;target=(157,139,137)
def marked(x,y):
 cx=round(x*scale);cy=round(y*scale+(1080-940*scale)/2);samples=[]
 for py in range(cy-4,cy+5):
  for px in range(cx-4,cx+5):
   start=(py*1920+px)*3;color=tuple(raw[start:start+3]);samples.append(color)
 return any(all(abs(a-b)<4 for a,b in zip(color,target)) for color in samples)
report={'input':str(p),'expectedByIndependentReview':'第三细胞标记落在支撑曲线起点(895,501)，原错误间隙(893,455)不保留标记','oldGapMarked':marked(893,455),'supportCurveMarked':marked(895,501)}
print(json.dumps(report,ensure_ascii=False,indent=2));assert report['oldGapMarked'] is False and report['supportCurveMarked'] is True
